// Bolt sprites for mods, v1.0.0. GENERATED by brand/bolt-sprites/tools/build.py: edit design.py, not this file.
// Copy this file into your mod's hooks/ folder (mods install on their own, so they cannot import from brand/).
// Rules (brand/BRAND.md): pink is the antenna light only, blush the cheeks only. Never recolour, rotate or stretch.
// Never draw Bolt over a safety hold, and never in a toast (toasts are uncoloured text).

export const BOLT_PALETTE = {
  B: '#C8F53C',
  S: '#9BC21A',
  O: '#FF5C8A',
  K: '#FF8FB1',
  E: '#101114',
  W: '#FBFBF8',
  G: '#8E95A3',
} as const

export type BoltSize = 'small' | 'tiny'
export type BoltSmallPose = 'idle' | 'run1' | 'run2' | 'jump' | 'crash' | 'cheer' | 'sleep' | 'sweat' | 'think' | 'egg' | 'egg-wobble-l' | 'egg-wobble-r' | 'egg-crack-1' | 'egg-crack-2' | 'egg-crack-3' | 'egg-hatch'
export type BoltTinyPose = 'idle' | 'run1' | 'run2' | 'jump' | 'crash' | 'cheer' | 'sleep'
export type BoltPose = BoltSmallPose | BoltTinyPose

/** One text cell: a character and its colours (absent = the surface's own). */
export type BoltCell = { ch: string; fg?: string; bg?: string }

/** Pixel rows: one palette letter per pixel, '.' empty. Heights are even (two pixel rows per cell). */
export const BOLT_SPRITES = {
  small: {
    'idle': ['....OO....', '....SS....', '..BBBBBB..', '.BBBBBBBB.', 'BBWEBBWEBB', 'BBEEBBEEBB', 'BKKBBBBKKB', 'BBBBEEBBBB', '.SSSSSSSS.', '..SS..SS..'],
    'run1': ['...OO.....', '....SS....', '..BBBBBB..', '.BBBBBBBB.', 'BBBWEBBWEB', 'BBBEEBBEEB', 'BKKBBBBBKB', 'BBBBBEEBBB', '.SSSSSSSS.', 'SS......SS'],
    'run2': ['....OO....', '....SS....', '..BBBBBB..', '.BBBBBBBB.', 'BBBWEBBWEB', 'BBBEEBBEEB', 'BKKBBBBBKB', 'BBBBBEEBBB', '.SSSSSSSS.', '...SSSS...'],
